}
E
cd resources
cat > Author.json <<'E'
{
  "name": "Author",
  "path": "/authors",
  "table": "author",
  "itemsPerPage": 2,
  "properties": {
    "id": {"type": "integer", "identifier": true, "readOnly": true},
    "name": {"type": "string"}
  }
}
E
cat > Book.json <<'E'
{
  "name": "Book",
  "path": "/books",
  "query": "book.query.ts",
  "command": "book.command.ts",
  "itemsPerPage": 2,
  "input": {
    "title": {"type": "string", "required": true},
    "author_id": {"type": "integer", "required": true},
    "published": {"type": "boolean"}
  },
  "properties": {
    "id": {"type": "integer", "identifier": true},
    "title": {"type": "string"},
    "author": {"type": "string", "filterable": true},
    "published": {"type": "boolean"}
  }
}
E
cat > book.query.ts <<'E'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`
    SELECT b.id, b.title, a.name AS author, b.published
    FROM book b
    LEFT JOIN author a ON a.id = b.author_id
    WHERE b.published`;
}
E
cat > book.command.ts <<'E'
function nameless(ctx, authorId) {
  const [a] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${authorId}`);
  return !!a && (a.name === null || String(a.name).trim() === "");
}
function refuse(ctx) {
  ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", status: 422 });
}
export function create(input, ctx) {
  const pub = input.published === true;
  if (pub && nameless(ctx, input.author_id)) refuse(ctx);
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${pub}) RETURNING id`);
  return row.id;
}
export function update(input, ctx) {
  const [cur] = ctx.db.query(ctx.sql`SELECT author_id, published FROM book WHERE id = ${ctx.id}`);
  const authorId = "author_id" in input ? input.author_id : cur.author_id;
  const pub = "published" in input ? input.published : cur.published;
  if (pub && nameless(ctx, authorId)) refuse(ctx);
  if ("title" in input) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if ("author_id" in input) ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  if ("published" in input) ctx.db.exec(ctx.sql`UPDATE book SET published = ${input.published} WHERE id = ${ctx.id}`);
}
export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
E
cat > Quote.json <<'E'
{
  "name": "Quote",
  "path": "/quotes",
  "query": "quote.query.ts",
  "itemsPerPage": 2,
  "allow": {"fetch": ["127.0.0.1:18090"]},
  "properties": {
    "id": {"type": "integer", "identifier": true},
    "text": {"type": "string"},
    "author": {"type": "string", "filterable": true}
  }
}
E
cat > quote.query.ts <<'E'
export default async function query(ctx) {
  const res = await ctx.fetch("http://127.0.0.1:18090/quotes.json");
  let rows = (await res.json()).map((q) => ({ id: q.id, text: q.quote, author: q.by }));
  rows.sort((a, b) => a.id - b.id);
  if (ctx.operation === "item") return rows.find((r) => r.id === ctx.id) ?? null;
  if (ctx.filters.author !== undefined) rows = rows.filter((r) => r.author === ctx.filters.author);
  const start = (ctx.page - 1) * ctx.itemsPerPage;
  return { items: rows.slice(start, start + ctx.itemsPerPage), totalItems: rows.length };
}
E
cat > Export.json <<'E'
{
  "name": "AuthorReport",
  "operations": [
    {"method": "GET", "path": "/business/export", "format": "csv", "query": "export.query.ts"}
  ],
  "properties": {
    "author": {"type": "string"},
    "published_books": {"type": "integer"}
  }
}
E
cat > export.query.ts <<'E'
export default function query(ctx: QueryContext): Sql {
  return ctx.sql`
    SELECT a.name AS author, count(b.id)::int AS published_books
    FROM author a
    LEFT JOIN book b ON b.author_id = a.id AND b.published
    WHERE a.name IS NOT NULL AND a.name <> ''
    GROUP BY a.id, a.name
    ORDER BY a.name COLLATE "C", a.id`;
}
E
cd ..; (./caddy run > caddy.log 2>&1 &); sleep 4
curl -s localhost:8089/mcp -H 'Content-Type: application/json' -d '{"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"validate","arguments":{}}}'

